<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- species grid + item icon HTML from snapshot */
  import type { QuestCardStructured } from '../../bus/snapshots.js';

  let {
    cardClass,
    borderLeft,
    data,
  }: {
    cardClass: string;
    borderLeft?: string;
    data: QuestCardStructured;
  } = $props();
</script>

<div class={cardClass} style:border-left={borderLeft ?? undefined}>
  <div class="quest-header">
    <span class="quest-badge {data.badgeClass}" title={data.badgeTitle ?? undefined}>{data.badgeText}</span>
    <h4 class="quest-title">
      <span class="quest-title-text">{data.title}</span>
      {#if data.repeatBadgeText}
        <span class="quest-repeat-badge" title={data.repeatBadgeTitle}>{data.repeatBadgeText}</span>
      {/if}
    </h4>
    {#if data.actions.abandon}
      <button
        type="button"
        class="quest-abandon-icon"
        data-action="abandonQuest"
        data-arg={data.questId}
        aria-label={data.actions.abandon}
      >✕</button>
    {/if}
  </div>
  <p class="quest-description">
    {#if data.descriptionHtml}{@html data.descriptionHtml}{:else}{data.description}{/if}
  </p>
  {#if data.dialogue}
    <div class="quest-dialogue" title={data.dialogue}>
      "{#if data.dialogueHtml}{@html data.dialogueHtml}{:else}{data.dialogue}{/if}"
    </div>
  {/if}
  {#if data.extraHtml}
    <div class="quest-extra">{@html data.extraHtml}</div>
  {/if}
  {#if !data.hasIvGate}
    <div class="quest-progress-container">
      <div class="quest-progress-bar">
        <div class="quest-progress-fill" style:width={`${data.percent}%`}></div>
      </div>
      <div class="quest-progress-text">{data.progressText}</div>
    </div>
  {/if}
  <div class="quest-foot">
    <div class="quest-rewards">
      {#if data.rewards.length > 0}
        {#each data.rewards as reward (reward.key)}
          <span
            class="quest-reward-item"
            data-tooltip-title={reward.tooltipTitle ?? undefined}
          >
            {#if reward.img}
              <img src={reward.img} class={reward.imgClass ?? 'quest-reward-inline-img'} alt="" />
            {/if}
            {#if reward.icon}<span class="quest-reward-icon">{@html reward.icon}</span>{/if}
            {reward.text}
          </span>
        {/each}
      {/if}
    </div>
    <div class="quest-actions">
      {#if data.actions.invalid}
        <div style="color:#94a3b8;font-size:12px;">{data.actions.invalid}</div>
      {:else if data.actions.accept && data.actions.refuse}
        <button class="quest-btn btn-accept" data-action="acceptQuest" data-arg={data.questId}>{data.actions.accept}</button>
        <button class="quest-btn btn-refuse" data-action="refuseQuest" data-arg={data.questId}>{data.actions.refuse}</button>
      {:else if data.actions.claim}
        <button class="quest-btn btn-claim" data-action="showQuestCompletionModal" data-arg={data.questId}>{data.actions.claim}</button>
      {:else if data.actions.storyNote}
        <div style="color:#94a3b8;font-size:12px;">{data.actions.storyNote}</div>
      {/if}
      {#if data.actions.goToZone}
        <button class="quest-btn btn-go-zone" data-action="goToQuestZone" data-arg={data.actions.goToZone.zoneId}>
          📍 Aller à {data.actions.goToZone.label}
        </button>
      {/if}
      {#if data.actions.goToTower}
        <button class="quest-btn btn-go-tower" data-action="switchTab" data-arg="tower">
          🗼 {data.actions.goToTower}
        </button>
      {/if}
    </div>
  </div>
</div>
