<script lang="ts">
  let {
    iconUrl,
    iconAlt = '',
    fallbackEmoji,
    title,
    description,
  }: {
    iconUrl?: string;
    iconAlt?: string;
    fallbackEmoji: string;
    title: string;
    description: string;
  } = $props();
</script>

<div class="story-quests-header">
  <div class="story-quests-header-icon">
    {#if iconUrl}
      <img
        src={iconUrl}
        alt={iconAlt}
        class="story-quest-section-chen"
        onerror={(e) => {
          const img = e.currentTarget as HTMLImageElement;
          img.style.display = 'none';
          const fb = img.nextElementSibling as HTMLElement | null;
          if (fb) fb.classList.add('visible');
        }}
      />
    {/if}
    <span class="story-quest-section-chen-fallback" class:visible={!iconUrl}>{fallbackEmoji}</span>
  </div>
  <div class="story-quests-header-text">
    <h3 class="story-quests-section-title">{title}</h3>
    <p class="story-quests-section-desc">{description}</p>
  </div>
</div>
