<script lang="ts">
  import { quests } from '../stores/quests.svelte.ts';
  import QuestList from './QuestList.svelte';
  import AchievementList from './AchievementList.svelte';
  import { game } from '../../gameManager.ts';
  import { bindQuestSpeciesGridTooltipEvents } from '../../questSystem.ts';
  import { bindQuestRewardTooltipEvents } from '../lib/questRewardTooltips.ts';

  let snap = $derived(quests.snapshot);
  let achSnap = $derived(quests.achievements);
  let ui = $derived(snap.ui);
  let achievementsMounted = $state(false);
  let storyEl: HTMLDivElement | undefined = $state();
  let dailyEl: HTMLDivElement | undefined = $state();
  let weeklyEl: HTMLDivElement | undefined = $state();

  interface SubTabBadgeCounts {
    claim: number;
    accept: number;
    inProgress: number;
  }

  function countQuestCardBadges(
    cards: Array<{ cardClass: string }>,
  ): SubTabBadgeCounts {
    let claim = 0;
    let accept = 0;
    let inProgress = 0;
    for (const card of cards) {
      const tokens = (card.cardClass || '').split(/\s+/);
      if (tokens.includes('completed')) {
        claim++;
      } else if (tokens.includes('accepted')) {
        inProgress++;
      } else {
        accept++;
      }
    }
    return { claim, accept, inProgress };
  }

  let storyBadges = $derived.by((): SubTabBadgeCounts => {
    const cards = [
      ...(snap.storySection?.quests ?? []),
      ...(snap.rocketSection?.quests ?? []),
    ];
    return countQuestCardBadges(cards);
  });

  let dailyBadges = $derived(countQuestCardBadges(snap.classicQuests));

  let weeklyBadges = $derived.by((): SubTabBadgeCounts => {
    if (!snap.weeklySection.unlocked) {
      return { claim: 0, accept: 0, inProgress: 0 };
    }
    let claim = 0;
    let inProgress = 0;
    for (const ch of snap.weeklySection.challenges) {
      const tokens = (ch.cardClass || '').split(/\s+/);
      if (ch.cardHtml.includes('data-action="claimWeeklyChallenge"')) {
        claim++;
      } else if (!tokens.includes('completed')) {
        inProgress++;
      }
    }
    return { claim, accept: 0, inProgress };
  });

  function hasAnyBadge(b: SubTabBadgeCounts): boolean {
    return b.claim > 0 || b.accept > 0 || b.inProgress > 0;
  }

  let claimTitle = $derived(
    typeof game?.t === 'function'
      ? game.t('tabBadge.questClaimTitle')
      : ui.language === 'en'
        ? 'Reward(s) to claim'
        : 'Récompense(s) à récupérer',
  );
  let acceptTitle = $derived(
    typeof game?.t === 'function'
      ? game.t('tabBadge.questAcceptTitle')
      : ui.language === 'en'
        ? 'Quest(s) to accept'
        : 'Quête(s) à accepter',
  );
  let inProgressTitle = $derived(
    ui.language === 'en' ? 'Quests in progress' : 'Quêtes en cours',
  );

  $effect(() => {
    const gm = game;
    if (!gm) return;
    for (const el of [storyEl, dailyEl, weeklyEl]) {
      if (!el) continue;
      bindQuestSpeciesGridTooltipEvents(el, gm);
      bindQuestRewardTooltipEvents(el, gm);
    }
  });

  function mountAchievementsIfNeeded(): void {
    if (!achievementsMounted) achievementsMounted = true;
  }

  $effect(() => {
    if (document.getElementById('questsSubView-succes')?.classList.contains('active')) {
      mountAchievementsIfNeeded();
    }
    const onSuccesTab = () => mountAchievementsIfNeeded();
    window.addEventListener('poketime:questsSuccesTab', onSuccesTab);
    return () => window.removeEventListener('poketime:questsSuccesTab', onSuccesTab);
  });
</script>

<!-- Cible = #questsTab -->
<div class="sub-tabs-container" role="tablist" aria-label={ui.subTabsAriaLabel}>
  <button id="questsSubTab-story" type="button" class="sub-tab-btn active" role="tab"
    aria-selected="true" aria-controls="questsSubView-story" tabindex="0"
    data-action="switchQuestsSubTab" data-arg="story">
    <span id="questsSubTabStoryLabel">{ui.subTabStory}</span>
    <span id="storySubTabBadge" class="quests-sub-tab-badge" style:display={hasAnyBadge(storyBadges) ? '' : 'none'}>
      {#if storyBadges.claim > 0}
        <span class="tab-badge tab-badge-claim" title={claimTitle}>{storyBadges.claim}</span>
      {/if}
      {#if storyBadges.accept > 0}
        <span class="tab-badge tab-badge-accept" title={acceptTitle}>{storyBadges.accept}</span>
      {/if}
      {#if storyBadges.claim === 0 && storyBadges.accept === 0 && storyBadges.inProgress > 0}
        <span class="tab-badge tab-badge-inprogress" title={inProgressTitle}>{storyBadges.inProgress}</span>
      {/if}
    </span>
  </button>
  <button id="questsSubTab-daily" type="button" class="sub-tab-btn" role="tab"
    aria-selected="false" aria-controls="questsSubView-daily" tabindex="-1"
    data-action="switchQuestsSubTab" data-arg="daily">
    <span id="questsSubTabDailyLabel">{ui.subTabDaily}</span>
    <span id="dailySubTabBadge" class="quests-sub-tab-badge" style:display={hasAnyBadge(dailyBadges) ? '' : 'none'}>
      {#if dailyBadges.claim > 0}
        <span class="tab-badge tab-badge-claim" title={claimTitle}>{dailyBadges.claim}</span>
      {/if}
      {#if dailyBadges.accept > 0}
        <span class="tab-badge tab-badge-accept" title={acceptTitle}>{dailyBadges.accept}</span>
      {/if}
      {#if dailyBadges.claim === 0 && dailyBadges.accept === 0 && dailyBadges.inProgress > 0}
        <span class="tab-badge tab-badge-inprogress" title={inProgressTitle}>{dailyBadges.inProgress}</span>
      {/if}
    </span>
  </button>
  <button id="questsSubTab-weekly" type="button" class="sub-tab-btn" role="tab"
    aria-selected="false" aria-controls="questsSubView-weekly" tabindex="-1"
    data-action="switchQuestsSubTab" data-arg="weekly">
    <span id="questsSubTabWeeklyLabel">{ui.subTabWeekly}</span>
    <span id="weeklySubTabBadge" class="quests-sub-tab-badge" style:display={hasAnyBadge(weeklyBadges) ? '' : 'none'}>
      {#if weeklyBadges.claim > 0}
        <span class="tab-badge tab-badge-claim" title={claimTitle}>{weeklyBadges.claim}</span>
      {/if}
      {#if weeklyBadges.accept > 0}
        <span class="tab-badge tab-badge-accept" title={acceptTitle}>{weeklyBadges.accept}</span>
      {/if}
      {#if weeklyBadges.claim === 0 && weeklyBadges.accept === 0 && weeklyBadges.inProgress > 0}
        <span class="tab-badge tab-badge-inprogress" title={inProgressTitle}>{weeklyBadges.inProgress}</span>
      {/if}
    </span>
  </button>
  <button id="questsSubTab-succes" type="button" class="sub-tab-btn" role="tab"
    aria-selected="false" aria-controls="questsSubView-succes" tabindex="-1"
    data-action="switchQuestsSubTab" data-arg="succes">
    <span id="questsSubTabSuccesLabel">{ui.subTabAchievements}</span>
    <span
      id="achievementsSubTabBadge"
      class={achSnap.claimableCount > 0 ? 'tab-badge tab-badge-claim' : ''}
      title={achSnap.claimableCount > 0 ? claimTitle : undefined}
    >{achSnap.claimableCount > 0 ? achSnap.claimableCount : ''}</span>
  </button>
</div>

<div class="sub-tab-content active" id="questsSubView-story">
  <div class="quest-container" id="questContainer" bind:this={storyEl}>
    <QuestList pane="story" />
  </div>
</div>

<div class="sub-tab-content" id="questsSubView-daily" hidden>
  <div class="quest-container" bind:this={dailyEl}>
    <QuestList pane="daily" />
  </div>
</div>

<div class="sub-tab-content" id="questsSubView-weekly" hidden>
  <div class="quest-container" bind:this={weeklyEl}>
    <QuestList pane="weekly" />
  </div>
</div>

<div class="sub-tab-content" id="questsSubView-succes" hidden>
  <h3 style="margin-top: 20px; margin-bottom: 12px;">
    <span id="achievementsTitleLabel">{ui.achievementsTitle}</span>
    (<span id="achievementsCount">{achSnap.achievementsCount}</span>/<span id="achievementsTotal">{achSnap.achievementsTotal}</span>)
  </h3>
  <div class="quest-container" id="achievementsContainer">
    {#if achievementsMounted}
      <AchievementList />
    {/if}
  </div>
</div>
