<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- empty state from questUiText i18n only */
  import { quests } from '../stores/quests.svelte.ts';
  import WeeklyChallengeList from './WeeklyChallengeList.svelte';
  import QuestCard from './quest/QuestCard.svelte';
  import QuestSectionHeader from './quest/QuestSectionHeader.svelte';
  import { getLazyListScrollRoot } from '../../formatters.ts';
  import { scheduleLazyBatch } from '../lib/scheduleLazyBatch.ts';

  const CLASSIC_QUEST_BATCH = 20;

  let { pane = 'story' }: { pane?: 'story' | 'daily' | 'weekly' } = $props();

  let snap = $derived(quests.snapshot);
  let ui = $derived(snap.ui);

  let visibleClassicCount = $state(CLASSIC_QUEST_BATCH);
  let classicListEl = $state<HTMLElement | null>(null);
  let classicSentinelEl = $state<HTMLDivElement | null>(null);
  let lastClassicIdsSig = $state('');

  let classicIdsSig = $derived(snap.classicQuests.map((q) => q.questId).join(','));

  let visibleClassicQuests = $derived(snap.classicQuests.slice(0, visibleClassicCount));
  let hasMoreClassic = $derived(visibleClassicCount < snap.classicQuests.length);

  $effect(() => {
    const sig = classicIdsSig;
    if (sig !== lastClassicIdsSig) {
      lastClassicIdsSig = sig;
      visibleClassicCount = Math.min(CLASSIC_QUEST_BATCH, snap.classicQuests.length);
    } else if (visibleClassicCount > snap.classicQuests.length) {
      visibleClassicCount = snap.classicQuests.length;
    }
  });

  $effect(() => {
    if (!classicSentinelEl || !hasMoreClassic) return;
    const scrollRoot = getLazyListScrollRoot(classicListEl, '.secondary-content');
    const io = new IntersectionObserver(
      (entries) => {
        if (!entries.some((e) => e.isIntersecting)) return;
        const len = snap.classicQuests.length;
        scheduleLazyBatch(() => {
          visibleClassicCount = Math.min(
            visibleClassicCount + CLASSIC_QUEST_BATCH,
            len,
          );
        });
      },
      { root: scrollRoot, rootMargin: '200px', threshold: 0 },
    );
    io.observe(classicSentinelEl);
    return () => io.disconnect();
  });
</script>

{#if pane === 'story' && snap.emptyMessage}
  <div style="text-align: center; color: #94a3b8; padding: 30px; font-style: italic;">
    {@html snap.emptyMessage}
  </div>
{:else if pane === 'story'}
  {#if snap.storySection}
    <div class="story-quests-section">
      <QuestSectionHeader {...snap.storySection.header} />
      <div class="story-quests-list">
        {#each snap.storySection.quests as card (card.questId)}
          <QuestCard
            cardClass={card.cardClass}
            borderLeft={card.borderLeft}
            data={card.structured}
          />
        {/each}
      </div>
    </div>
  {/if}

  {#if snap.rocketSection}
    <div data-unlock-key={snap.rocketSection.unlockKey ?? undefined} style:display={snap.rocketSection.visible ? '' : 'none'}>
      <div class="story-quests-section team-rocket-quests-section">
        <QuestSectionHeader {...snap.rocketSection.header} />
        <div class="story-quests-list">
          {#each snap.rocketSection.quests as card (card.questId)}
            <QuestCard
              cardClass={card.cardClass}
              borderLeft={card.borderLeft}
              data={card.structured}
            />
          {/each}
        </div>
      </div>
    </div>
  {/if}
{:else if pane === 'daily'}
  {#if snap.classicQuestsUnlocked || snap.classicQuests.length > 0}
    <div
      id="classicQuestsSection"
      data-unlock-key="classicQuests"
      style:display={snap.classicQuestsUnlocked ? '' : 'none'}
      bind:this={classicListEl}
    >
      <div class="classic-quests-daily-header" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; margin-top: 20px; flex-wrap: wrap; gap: 10px;">
        <div style="display: flex; align-items: center; gap: 12px; flex-wrap: wrap;">
          <h3 style="margin: 0;">
            <span id="dailyQuestsTitleLabel">{ui.dailyTitle}</span>
            (<span id="questCount">{snap.questCount}</span>/10)
          </h3>
          {#if snap.claimableCount >= 2}
            <button
              type="button"
              class="quest-claim-all-btn btn btn-save"
              data-action="claimAllQuests"
            >
              ✓ {ui.claimAll} ({snap.claimableCount})
            </button>
          {/if}
        </div>
        <div class="quest-timer quest-timer--pill" id="questTimer" role="status" aria-live="polite">
          <span id="nextQuestLabel">{ui.nextLabel}</span>
          <strong id="nextQuestTime">--:--</strong>
        </div>
      </div>
      {#each visibleClassicQuests as card (card.questId)}
        <QuestCard cardClass={card.cardClass} data={card.structured} />
      {/each}
      {#if hasMoreClassic}
        <div bind:this={classicSentinelEl} class="storage-scroll-sentinel" aria-hidden="true"></div>
      {/if}
    </div>
  {/if}
{:else if pane === 'weekly'}
  <WeeklyChallengeList />
{/if}
